import { useCallback, useEffect, useState } from 'react';
import { useRecoilValue } from 'recoil';
import { ConstantActions } from '../../../../Services/_actions';
import { convertGroupFormIntoArr, validateDynamicForm, validateFormFieldValue } from '../../../../components/Leads/DynamicFormFields/helper.ts';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { userInformationAtom } from '../../../../Services/_states';
import { isLeadIdField } from '../../../intervene/utils/leadFormFields';
import { recordService } from '../services/recordService';
import {
  buildRecordDynamicFormData,
  hasEditableRecordFormFields,
} from '../utils/recordFormFieldsUtils';
import { RECORD_COPY } from '../constants/recordCopy';

const ALLOWED_EXTENSIONS = ['jpg', 'jpeg', 'png', 'pdf', 'mp4'];
const MAX_FILE_SIZE = 10 * 1024 * 1024;

function isPhoneField(item) {
  const phoneIdentifiers = [item?.key_name, item?.label, item?.alias_name].map((value) =>
    String(value ?? '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '')
  );

  return (
    item?.key_type === 'PHONE' ||
    phoneIdentifiers.some((value) =>
      ['phone', 'phonenumber', 'mobile', 'mobilenumber'].includes(value)
    )
  );
}

function validateFileBeforeUpload(file) {
  const ext = file.name.split('.').pop()?.toLowerCase();
  if (!ext || !ALLOWED_EXTENSIONS.includes(ext)) {
    return `Invalid file type. Allowed: ${ALLOWED_EXTENSIONS.join(', ')}`;
  }
  if (file.size > MAX_FILE_SIZE) {
    return `File too large. Max allowed size is ${MAX_FILE_SIZE / (1024 * 1024)} MB`;
  }
  return null;
}

function buildWebFormFromTable(table, formPayload) {
  const payload = formPayload?.data ?? formPayload ?? {};
  const nested = payload?.leads_form_items
    ? payload
    : Object.values(payload).find(
        (entry) => entry && typeof entry === 'object' && entry.leads_form_items
      );

  return {
    leads_form_id: table?.id,
    leads_form_name: table?.name,
    leads_form_items: nested?.leads_form_items ?? table?.leadsFormItems ?? {},
    group_options: nested?.group_options ?? [],
    reference: nested?.reference,
    templates: nested?.templates ?? [],
  };
}

export default function useRecordForm({ table, onSaved }) {
  const constantActions = ConstantActions();
  const { showSnackBar } = useSnackBar();
  const loggedInUser = useRecoilValue(userInformationAtom);
  const profileId = loggedInUser?.profile?.id ?? loggedInUser?.id ?? '';

  const [drawerOpen, setDrawerOpen] = useState(false);
  const [mode, setMode] = useState('view');
  const [webForm, setWebForm] = useState(null);
  const [selectedRecord, setSelectedRecord] = useState(null);
  const [dynamicFormData, setDynamicFormData] = useState({});
  const [fieldErrors, setFieldErrors] = useState({});
  const [statusUpdate, setStatusUpdate] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [formDataLoading, setFormDataLoading] = useState(false);
  const [isFormDirty, setIsFormDirty] = useState(false);
  const [formEnable, setFormEnable] = useState(true);

  const isCreating = mode === 'create';
  const isReadOnly = mode === 'view' || (formEnable && !isCreating);
  const hasDynamicFields = hasEditableRecordFormFields(dynamicFormData);

  const buildFormState = useCallback((form, record) => {
    return buildRecordDynamicFormData(form, record, profileId);
  }, [profileId]);

  const loadFormDefinition = useCallback(async () => {
    if (!table?.id) return null;
    const res = await recordService.fetchFormDefinition(table.id);
    if (res?.status === 200 || res?.status === 201) {
      return buildWebFormFromTable(table, res.data);
    }
    return buildWebFormFromTable(table, null);
  }, [table]);

  const processRecordData = useCallback((record, form) => {
    if (!form) return;
    const normalized = {
      ...(record || {}),
      id: record?.id || record?.lead_id,
      lead_id: record?.lead_id || record?.id,
      phone_number: record?.phone_number || '',
    };
    setSelectedRecord(normalized);
    setDynamicFormData(buildFormState(form, normalized));
    setFieldErrors({});
    setStatusUpdate({});
    setIsFormDirty(false);
  }, [buildFormState]);

  const initBlankForm = useCallback((form) => {
    if (!form) return;
    setSelectedRecord({});
    setDynamicFormData(buildFormState(form, null));
    setFieldErrors({});
    setStatusUpdate({});
    setIsFormDirty(false);
    setFormEnable(false);
  }, [buildFormState]);

  const openCreate = useCallback(async () => {
    setMode('create');
    setDrawerOpen(true);
    setFormDataLoading(true);
    try {
      const form = await loadFormDefinition();
      setWebForm(form);
      initBlankForm(form);
    } finally {
      setFormDataLoading(false);
    }
  }, [initBlankForm, loadFormDefinition]);

  const openRecord = useCallback(async (rawLead, nextMode = 'view') => {
    if (!rawLead) return;
    setMode(nextMode);
    setDrawerOpen(true);
    setFormDataLoading(true);
    try {
      const form = await loadFormDefinition();
      setWebForm(form);

      const mongoId = rawLead._mongoId || rawLead.id;
      if (mongoId && nextMode !== 'create') {
        const res = await recordService.fetchRecordById(mongoId);
        if (res?.status === 200) {
          processRecordData(res.data?.data ?? res.data, form);
          setFormEnable(nextMode === 'view');
          return;
        }
      }
      processRecordData(rawLead._rawLead ?? rawLead, form);
      setFormEnable(nextMode === 'view');
    } catch (err) {
      showSnackBar(RECORD_COPY.errors.loadRecord, 'error');
      setDrawerOpen(false);
    } finally {
      setFormDataLoading(false);
    }
  }, [loadFormDefinition, processRecordData, showSnackBar]);

  const closeDrawer = useCallback(() => {
    setDrawerOpen(false);
    setMode('view');
    setSelectedRecord(null);
    setDynamicFormData({});
    setFieldErrors({});
    setStatusUpdate({});
    setIsFormDirty(false);
  }, []);

  const handleFieldChange = useCallback((index, value, groupTitle) => {
    const updatedData = { ...dynamicFormData };
    const groupForm = [...(updatedData[groupTitle] || [])];
    let updatedField = { ...groupForm[index], value };

    if (value && typeof value === 'object' && value?.collection === 'entity') {
      updatedField = { ...updatedField, entity_data: value ?? null, value: value?.value ?? '' };
    } else if (
      updatedField?.statusOption === 'is_status' ||
      updatedField?.statusOption === 'is_sub_status'
    ) {
      if (updatedField?.statusOption === 'is_status') {
        updatedField = {
          ...updatedField,
          status_config: value ?? null,
          value: value?.status_name ?? '',
        };
      } else if (updatedField?.statusOption === 'is_sub_status') {
        updatedField = { ...updatedField, status_config: value ?? null, value: value?.name ?? '' };
      }
      setStatusUpdate((prev) => {
        if (updatedField?.statusOption === 'is_status') {
          return {
            ...prev,
            status: {
              ...prev.status,
              [updatedField.key_name]: {
                status_id: value?.status_id ?? '',
                status_name: value?.status_name ?? '',
                type_of_status: value?.type_of_status ?? '',
                status: value?.status_name ?? '',
              },
            },
          };
        }
        if (updatedField?.statusOption === 'is_sub_status') {
          return {
            ...prev,
            sub_status: {
              ...(prev?.sub_status ?? {}),
              [updatedField.key_name]: {
                sub_status_id: value?.sub_status_id ?? '',
                sub_status_name: value?.name ?? '',
                type_of_status: value?.type_of_status ?? updatedField?.key_name ?? '',
                status_id: value?.status_id ?? '',
                status_name: value?.status_name ?? '',
              },
            },
          };
        }
        return prev;
      });
    }

    groupForm[index] = updatedField;
    updatedData[groupTitle] = groupForm;
    setDynamicFormData(updatedData);
    setIsFormDirty(true);

    const errorMsg = validateFormFieldValue(updatedField, value);
    if (errorMsg) {
      setFieldErrors((prev) => ({ ...prev, [`${groupTitle}_${index}`]: errorMsg }));
    } else {
      setFieldErrors((prev) => {
        const next = { ...prev };
        delete next[`${groupTitle}_${index}`];
        return next;
      });
    }
  }, [dynamicFormData]);

  const uploadFile = useCallback(async (file) => {
    const validationError = validateFileBeforeUpload(file);
    if (validationError) {
      showSnackBar(validationError, 'error');
      return '';
    }
    try {
      const formData = new FormData();
      formData.append('file', file);
      const resp = await constantActions.uploadFileS3Bucket(formData);
      if (resp?.status === 200 && resp?.data?.data?.url) {
        return resp.data.data.url;
      }
    } catch (error) {
      showSnackBar('File upload failed', 'error');
    }
    return '';
  }, [constantActions, showSnackBar]);

  const updateStatusInLoop = useCallback(async (leadId) => {
    if (!leadId) return;
    const statusPayloads = [
      ...Object.values(statusUpdate?.status ?? {}),
      ...Object.values(statusUpdate?.sub_status ?? {}),
    ]
      .filter(
        (item) => Boolean(item) && item?.status_id && (item?.status_name || item?.sub_status_name)
      )
      .map((item) => ({ ...item, id: leadId }));

    if (statusPayloads.length === 0) return;

    await Promise.allSettled(
      statusPayloads.map((payload) => recordService.updateLeadStatus(payload))
    );
  }, [statusUpdate]);

  const saveRecord = useCallback(async (phoneNumberOverride = '') => {
    if (!table?.id) return;

    const { fieldErrors: validationFieldErrors, hasErrors } = validateDynamicForm(dynamicFormData);
    if (hasErrors) {
      setFieldErrors(validationFieldErrors);
      showSnackBar('Please fill all required fields', 'error');
      return;
    }

    setIsLoading(true);
    try {
      const flatFields = convertGroupFormIntoArr(dynamicFormData).filter(
        (item) => !item?.is_static_column
          && !isLeadIdField(item)
          && item?.access_level !== 'none'
      );

      const processedEntries = await Promise.all(
        flatFields.map(async (item) => {
          if (item?.key_type === 'FILE' && item.value instanceof File) {
            const fileUrl = await uploadFile(item.value);
            return { ...item, value: fileUrl };
          }
          return item;
        })
      );

      let dynamicPhoneNumber = '';
      const entryList = processedEntries.map((item) => {
        if (isPhoneField(item) && item.value) {
          dynamicPhoneNumber = item.value;
        }
        return {
          key_name: item?.key_name,
          value: item?.entity_data?.value ? item?.entity_data?.value ?? '' : item?.value ?? '',
          ...(item?.entity_data && { entity_data: item?.entity_data ?? null }),
          ...(item?.status_config && { status_config: item?.status_config ?? null }),
        };
      });

      const phoneNumber = phoneNumberOverride || dynamicPhoneNumber || selectedRecord?.phone_number || '';

      if (!phoneNumber) {
        showSnackBar(RECORD_COPY.errors.phoneRequired, 'error');
        return;
      }

      const payload = {
        area: selectedRecord?.area || '',
        city: selectedRecord?.city || '',
        lead_id: selectedRecord?.lead_id || '',
        leads_form_entries: entryList,
        phone_number: phoneNumber,
        supplier_id: selectedRecord?.supplier_id || '',
        supplier_name: selectedRecord?.supplier_name || '',
        leads_form_id: parseInt(table.id, 10) || table.id,
        parent_id: { lead_id: '' },
      };

      const isUpdate = Boolean(selectedRecord?.id || selectedRecord?.lead_id) && !isCreating;
      const res = isUpdate
        ? await recordService.updateRecord(payload)
        : await recordService.createRecord(payload);

      if (res?.status === 200) {
        const leadIdAfterSave =
          res?.data?.data?.id ??
          res?.data?.id ??
          res?.data?.data?.lead_id ??
          selectedRecord?.id ??
          selectedRecord?.lead_id;

        await updateStatusInLoop(leadIdAfterSave);
        showSnackBar(RECORD_COPY.success.saved, 'success');
        setIsFormDirty(false);
        setMode('view');
        setFormEnable(true);
        onSaved?.();
      } else {
        showSnackBar(RECORD_COPY.errors.saveFailed, 'error');
      }
    } catch (err) {
      console.error(err);
      showSnackBar(RECORD_COPY.errors.saveFailed, 'error');
    } finally {
      setIsLoading(false);
    }
  }, [
    dynamicFormData,
    isCreating,
    onSaved,
    selectedRecord,
    showSnackBar,
    table?.id,
    updateStatusInLoop,
    uploadFile,
  ]);

  const deleteRecord = useCallback(async (rawLead) => {
    const leadId = rawLead?.lead_id ?? rawLead?._rawLead?.lead_id;
    if (!leadId) return false;

    try {
      const res = await recordService.deleteRecords([leadId]);
      if (res?.status === 200) {
        showSnackBar(RECORD_COPY.success.deleted, 'success');
        onSaved?.();
        return true;
      }
      showSnackBar(RECORD_COPY.errors.deleteFailed, 'error');
    } catch (err) {
      showSnackBar(RECORD_COPY.errors.deleteFailed, 'error');
    }
    return false;
  }, [onSaved, showSnackBar]);

  const startEdit = useCallback(() => {
    setMode('edit');
    setFormEnable(false);
  }, []);

  const discardChanges = useCallback(() => {
    if (isCreating) {
      closeDrawer();
      return;
    }

    if (mode === 'view' || formEnable) {
      closeDrawer();
      return;
    }

    processRecordData(selectedRecord, webForm);
    setMode('view');
    setFormEnable(true);
    setIsFormDirty(false);
  }, [closeDrawer, formEnable, isCreating, mode, processRecordData, selectedRecord, webForm]);

  const requestCloseDrawer = useCallback(() => {
    if (isCreating) {
      closeDrawer();
      return;
    }

    if (mode === 'edit' && isFormDirty) {
      processRecordData(selectedRecord, webForm);
      setMode('view');
      setFormEnable(true);
      setIsFormDirty(false);
    }

    closeDrawer();
  }, [
    closeDrawer,
    isCreating,
    isFormDirty,
    mode,
    processRecordData,
    selectedRecord,
    webForm,
  ]);

  useEffect(() => {
    if (!drawerOpen) {
      setWebForm(null);
    }
  }, [drawerOpen]);

  return {
    drawerOpen,
    mode,
    webForm,
    selectedRecord,
    dynamicFormData,
    fieldErrors,
    isLoading,
    formDataLoading,
    isFormDirty,
    formEnable,
    isReadOnly,
    isCreating,
    hasFormFields: hasDynamicFields,
    canCreateRecord: isCreating || hasDynamicFields,
    openCreate,
    openRecord,
    closeDrawer,
    handleFieldChange,
    saveRecord,
    deleteRecord,
    startEdit,
    discardChanges,
    requestCloseDrawer,
  };
}
